text:
// Pawn Champ - The Polar Plunge. Minor quest m25, batch N (docs/quests/MINOR.md#m25-the-polar-plunge).
// Winnie Albrecht, president of the Frostbite Club, lost her late husband's signet ring in the New
// Year's Day plunge. A boy found it in the sand at the breakwater and pawned it. Winnie will buy it
// back, and she has a bet for you: come in the water with the club on their January dip.
// January only, in a stay. The dip is at the breakwater (`plungeBeach`, drawn in the code half).
//
// Written as data: docs/STORY_DATA.md. Strict JSON inside the call. Code half: js/quests/plunge.js.
defineStory({
  "id": "plunge",
  "kind": "minor",
  "title": "The Polar Plunge",
  "location": "sandbar",
  "months": [4],
  "rumour": "Winnie Albrecht lost her husband's ring in the New Year's plunge, and went back in for it twice.",
  "endings": { "returned": "Gave It Back", "plunged": "In the Drink", "double": "Paid Double", "melted": "Melted Down" },
  "outcome": "flag.plungeEnd",
  "about": [
    "A January story. Kip Szymanski pawns a gold heron signet ring he found in the sand after the New Year's plunge (§{plungeKip}). Winnie Albrecht, president of the Frostbite Club, lost her late husband Harold's ring in that plunge and went back in for it twice (§{plungeWinnie}).",
    "Give it back free (Gave It Back), sell it for scrap (Melted Down), or take her bet: join the club's January dip at the breakwater and she buys it back at cost; stay on the sand and she pays double and calls you a coward, lovingly (§{plungeDip}). Go in (In the Drink) or stay dry (Paid Double)."
  ],
  "cast": {
    "winnie": {
      "name": "Winnie Albrecht",
      "look": { "skin": "#f0d0b8", "hair": "#e8e8ec", "hs": 4, "coat": "#e86a8a", "trim": "#f4f0e4", "style": "puffer", "long": true, "pants": "#2a4a6a", "hat": "beanie", "hatc": "#f4f0e4" }
    },
    "kipS": {
      "name": "Kip Szymanski",
      "look": { "skin": "#f0c8a8", "hair": "#c8862a", "hs": 1, "coat": "#3a6a3a", "trim": "#2a2a2a", "style": "hoodie", "pants": "#3a3a5a", "hat": "beanie", "hatc": "#e8a020" }
    }
  },
  "icons": {
    "heronRing": [
      "............",
      "....kkkk....",
      "...kyYYyk...",
      "..kyYSSYyk..",
      "..kySdkSyk..",
      "..kyYSSYyk..",
      "..ky.kk.yk..",
      "..ky....yk..",
      "..ky....yk..",
      "...kyooyk...",
      "....kkkk....",
      "............"
    ]
  },
  "uniques": {
    "heronRing": {
      "name": "A gold signet ring with a heron",
      "icon": "heronRing",
      "cat": "jewelry",
      "guide": 90,
      "condLabel": "Sand in the engraving",
      "questKey": true,
      "tells": [
        "A man's signet ring, 14k, a heron cut into the face. Sand still in the lines of it.",
        "Inside the band: W.A. to H.A. 1971."
      ]
    }
  },
  "spots": {
    "plungeBeach": [
      {
        "id": "banner",
        "rect": { "x": 260, "y": 186, "w": 180, "h": 22 },
        "lines": [
          "FROSTBITE CLUB JAN DIP. The club has met every January since 1958. Its motto is in Latin. Nobody remembers what it says."
        ]
      },
      {
        "id": "towels",
        "rect": { "x": 116, "y": 294, "w": 90, "h": 16 },
        "lines": [
          "Towels laid out on the rocks, warmed by the barrel. One says PROPERTY OF THE HARBORVIEW MOTOR INN."
        ],
        "where": "the breakwater",
        "find": { "on": 1, "coin": 2, "line": "Two dollars under a towel, left for the cocoa kitty. You put it in the kitty. Then you take it out again." }
      }
    ]
  },
  "scenes": {
    "plungeKip": {
      "title": "Kip Szymanski pawns a ring he found on the beach",
      "customer": "kipS",
      "steps": [
        {
          "say": "kipS",
          "text": [
            "Found this on the beach by the breakwater on New Year's Day. In the sand. After the plunge thing, when everyone had gone home blue.",
            "It's gold, right? It's heavy. Thirty bucks?"
          ]
        },
        { "offer": { "unique": "heronRing" }, "persona": "honest", "asking": 30, "min": 20 },
        {
          "if": "offer != 'deal'",
          "then": [
            { "say": "kipS", "text": "I'll try the gold place on Route 1, then. They don't ask where you found stuff." },
            { "leave": "kipS" },
            { "end": true }
          ]
        },
        { "set": { "plungeIn": true } },
        { "leave": "kipS" }
      ]
    },
    "plungeWinnie": {
      "title": "Winnie Albrecht comes looking for Harold's ring, with a bet",
      "customer": "winnie",
      "steps": [
        {
          "say": "winnie",
          "text": [
            "Winnie Albrecht. President of the Frostbite Club, forty-one years. You'll have heard. I went in on New Year's Day with Harold's ring on my thumb and came out without it.",
            "I went back in for it. Twice. Dot Haskell had to fetch me out the second time with a boat hook."
          ]
        },
        { "find": "ring", "in": "stock", "match": { "uniqueId": "heronRing" } },
        {
          "if": "!ring",
          "then": [
            { "say": "winnie", "text": "If a ring with a heron on it ever comes in, you ring me. Day or night. I don't sleep, I swim." },
            { "leave": "winnie" },
            { "end": true }
          ]
        },
        { "narrate": "You put the heron ring on the counter. Winnie doesn't say anything. She puts her hand flat over it, the way you'd cover a bird." },
        {
          "say": "winnie",
          "text": [
            "Right. Here's what. Harold would have liked this. Saturday is the club's January dip at the breakwater. Come in the water with us and I'll buy it back at whatever you paid.",
            "Stay on the sand in your coat and I'll pay double, and tell everyone in town you're a coward. Lovingly."
          ]
        },
        {
          "choose": [
            {
              "label": "Give it back now, free",
              "hint": "(the story ends here)",
              "then": [
                { "take": "ring" },
                { "rep": 3, "why": "Gave Winnie Albrecht her husband's ring" },
                { "set": { "plungeEnd": "returned" } },
                { "say": "winnie", "text": "Oh, you soft thing. Come to the dip anyway. There's cocoa." }
              ]
            },
            {
              "label": "Take the bet",
              "hint": "(the dip, at lunch)",
              "then": [
                { "set": { "plungeBet": true } },
                { "plan": "plunge-dip" },
                { "say": "winnie", "text": "Ha! Bring a towel. Bring two. Don't bring dignity, it doesn't float." }
              ]
            },
            {
              "label": "Sell it to the gold buyer instead",
              "hint": "(+$45; the story ends here)",
              "then": [
                { "take": "ring" },
                { "coin": 45, "why": "Sold a gold signet ring for scrap" },
                { "rep": -3 },
                { "set": { "plungeEnd": "melted" } },
                { "say": "winnie", "text": "For scrap. Well. Harold was always worth more than his weight. Good day." }
              ]
            }
          ]
        },
        { "leave": "winnie" }
      ]
    },
    "plungeDip": {
      "title": "The Frostbite Club's January dip",
      "steps": [
        {
          "stage": "plungeBeach",
          "fadeOut": false,
          "actors": [
            { "id": "you", "cast": "keeper", "name": "You", "at": [110, 168] },
            { "id": "winnie", "cast": "winnie", "at": [180, 166], "facingLeft": true },
            { "id": "dot", "cast": "dot", "at": [240, 166], "facingLeft": true, "if": "hook.dotHere" }
          ]
        },
        { "narrate": "The breakwater at noon. Nineteen degrees, a wind off the harbor mouth, and thirty people in bathing suits and woolly hats stamping on the sand. Somebody has a bugle." },
        { "say": "dot", "text": "I've got the boat hook. I've got cocoa. I've got a blanket that's seen things. Go on.", "if": "dot" },
        { "say": "winnie", "text": "On the bugle. In to the waist, under once, out. Harold did it in 1971 with me on his back." },
        { "find": "ring", "in": "stock", "match": { "uniqueId": "heronRing" } },
        {
          "choose": [
            {
              "label": "Go in",
              "then": [
                {
                  "narrate": [
                    "The water isn't cold. It is something past cold, a white noise all over your skin. You go under once and come up shouting a word you didn't know you knew.",
                    "Thirty people in woolly hats cheer. Winnie wraps you in a towel with a heron on it."
                  ]
                },
                {
                  "if": "ring",
                  "then": [
                    { "take": "ring" },
                    {
                      "hook": "buyBack",
                      "with": { "times": 1, "why": "Winnie Albrecht bought back Harold's ring" }
                    }
                  ]
                },
                { "rep": 4, "why": "Did the Frostbite Club's January dip" },
                { "set": { "plungeEnd": "plunged" } },
                { "say": "winnie", "text": "There. Now you're one of us. That's a life sentence, by the way." }
              ]
            },
            {
              "label": "Stay on the sand in your coat",
              "then": [
                {
                  "if": "ring",
                  "then": [
                    { "take": "ring" },
                    {
                      "hook": "buyBack",
                      "with": { "times": 2, "why": "Winnie Albrecht paid double for Harold's ring" }
                    }
                  ]
                },
                { "rep": -1 },
                { "set": { "plungeEnd": "double" } },
                { "narrate": "Winnie pays you double out of a zip bag, in front of everyone, and goes in on the bugle with her ring on a string round her neck." },
                { "say": "winnie", "text": "(from the water) COWARD! Lovingly!" }
              ]
            }
          ]
        }
      ]
    }
  },
  "beats": [
    { "drift": "plunge", "from": "1-2", "to": "2-2", "cast": "kipS", "scene": "plungeKip" },
    { "drift": "plunge", "from": "1-2", "to": "2-2", "offset": 3, "cast": "winnie", "scene": "plungeWinnie", "if": "!flag.plungeEnd" }
  ],
  "errands": [
    {
      "id": "plunge-dip",
      "title": "The Frostbite Club's January dip",
      "where": "The breakwater",
      "scene": "plungeDip",
      "test": [{ "add": { "unique": "heronRing" } }, { "set": { "plungeBet": true } }]
    }
  ],
  "calendar": [
    { "id": "plunge-dip", "errand": "plunge-dip", "story": "plunge", "where": "The breakwater", "title": "The January dip", "known": "flag.plungeBet" }
  ],
  "epilogue": [
    { "line": "Winnie Albrecht wears Harold's ring on a chain now. She still swims every January. So, she says, does he.", "if": "flag.plungeEnd == 'returned'" },
    { "line": "You are a member of the Frostbite Club for life. The card came in the mail. It's laminated, in case.", "if": "flag.plungeEnd == 'plunged'" },
    { "line": "Winnie Albrecht tells everyone you're a coward, lovingly. She also tells them you gave her back Harold's ring.", "if": "flag.plungeEnd == 'double'" },
    { "line": "Harold Albrecht's heron ring was melted down on Route 1. Winnie still swims every January, and doesn't come into the shop.", "if": "flag.plungeEnd == 'melted'" }
  ],
  "talk": {
    "by": "dot",
    "rumour": [
      "Winnie Albrecht lost Harold's ring in the New Year's plunge. She went back in for it. Twice. I had to fetch her out with a boat hook.",
      "Seventy-eight, in the harbor in January, diving for a ring. I've never been so frightened or so proud."
    ],
    "react": { "returned": "Winnie's got Harold's ring back. She came in for a chowder and cried in it. Then she said it needed salt.", "plunged": "I hear you went in with the Frostbite Club. On the bugle. In January. I've got a photo. It's going on the wall.", "double": "Winnie says you stood on the sand in your coat. She also says you're a sweetheart. Both, I think.", "melted": "You sold Harold Albrecht's ring for scrap. Winnie hasn't said a word about it, which is worse than anything she could say." }
  }
});
